  "pathShared": {
   "eyebrow": "Твой кармический путь",
   "primaryAction": "Найти свой первый урок",
   "moreAction": "Глубже о моём пути",
   "recognitionTitle": "Где ты сейчас узнаёшь эту тему?",
   "recognitionSubtitle": "В разные периоды она проявляется по-разному. Отметь знакомое или выбери свою историю.",
   "otherStory": "Сейчас у меня другая история",
   "foundation": {
    "title": "Почему знакомые сюжеты возвращаются",
    "paragraphs": [
     "В «Пути кармы» мы исследуем повторяющиеся сюжеты: люди меняются, а знакомое чувство и привычный ответ возвращаются. Например, снова соглашаешься против желания, пытаешься заслужить внимание или споришь там, где хотелось бы договориться.",
     "Число открывает общую тему твоего пути. Учителя помогают увидеть, как она проявляется в жизни: это люди и ситуации, рядом с которыми особенно заметна твоя привычная реакция. Увидеть учителя — значит найти конкретный случай, с которым хочется разобраться.",
     "Пройти урок — научиться замечать момент выбора и пробовать ответ, который больше подходит тебе. Иногда это просьба, иногда граница, разговор или пауза. Из таких небольших действий складывается новый опыт — его мы и будем отмечать. Менять другого человека для этого не требуется."
    ]
   },
   "readingCards": [
    {
     "id": "karma-scene",
     "title": "Как узнать знакомый сюжет",
     "text": "Вспомни не всех похожих людей, а один повторяющийся момент: что происходит, что ты чувствуешь и как обычно отвечаешь. Так большая история превращается в случай, с которым можно работать."
    },
    {
     "id": "karma-teacher",
     "title": "Кого мы называем учителем",
     "text": "Учитель — человек или ситуация, рядом с которыми проявляется привычный ответ. Это название роли в твоём исследовании. Чужой поступок остаётся чужим; свой выбор ты ищешь в том, что можешь сделать дальше."
    },
    {
     "id": "karma-lesson",
     "title": "Как понять свой урок",
     "text": "Урок звучит как умение: попросить, уточнить, отказаться, выдержать неопределённость или выбрать своё действие. Если формулировка не помогает понять, что попробовать в жизни, её стоит уточнить."
    },
    {
     "id": "karma-change",
     "title": "Как замечать перемены",
     "text": "Сравнивай конкретные случаи: раньше замолкал, а сейчас назвал просьбу; раньше соглашался сразу, а сейчас проверил свои силы. Записывай и трудные попытки. Новый ответ складывается из опыта, а не из одного идеального дня."
    }
   ]
  },
  "pathLinks": {
   "1|ev-myway@work": "В твоём пути самостоятельность сейчас проявляется в рабочей договорённости: какой результат нужен и что ты можешь решать сам.",
   "1|ev-decide@work": "В твоём пути самостоятельность сейчас проявляется в участии в решениях, которые касаются твоей работы.",
   "1|ev-decide@close": "В твоём пути самостоятельность сейчас проявляется в том, чтобы участвовать в общих решениях, а не узнавать о них последним.",
   "2|ev-ask@close": "В твоём пути партнёрство сейчас проявляется в праве ответить на просьбу близкого так, как подходит и тебе.",
   "3|ev-interrupt@close": "В твоём пути самовыражение сейчас проявляется в том, чтобы договорить важное до конца.",
   "6|ev-ask@work": "В твоём пути забота сейчас проявляется в том, чтобы помогать по силам и проверять свою нагрузку до ответа.",
   "8|ev-myway@work": "В твоём пути влияние сейчас проявляется в праве договариваться о полномочиях в своей задаче.",
   "5|ev-myway@work": "В твоём пути свобода сейчас проявляется в том, чтобы вернуть себе выбор способа в рабочей задаче.",
   "8|ev-contrib@work": "В твоём пути влияние сейчас проявляется в том, чтобы называть ценность своего вклада и условия.",
   "6|ev-deadline@work": "В твоём пути забота сейчас проявляется в том, чтобы сказать о своей нагрузке, а не тянуть всё молча.",
   "3|ev-interrupt@work": "В твоём пути самовыражение сейчас проявляется в том, чтобы договорить свою мысль на работе."
  },
